pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        try c.XBornID() {} catch { return; }
        uint256 td;
        try c.totalDistributed() returns (uint256 __r) { td = __r; } catch { return; }
        uint256 balCaller;
        try c.balanceOf(caller) returns (uint256 __r) { balCaller = __r; } catch { return; }
        assertTrue(!(caller != address(this) && balCaller == td));
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
